-- Generated by scripts/store-p3/make-upgrade-fixtures.mjs. Synthetic data only.
PRAGMA foreign_keys = OFF;
BEGIN;
CREATE TABLE users (
    id TEXT PRIMARY KEY,
    email TEXT UNIQUE NOT NULL,
    username TEXT UNIQUE NOT NULL,
    password_hash TEXT NOT NULL,
    full_name TEXT,
    avatar_url TEXT,
    role TEXT NOT NULL DEFAULT 'user' CHECK(role IN ('owner', 'admin', 'user', 'guest')),
    status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active', 'inactive', 'suspended')),
    email_verified INTEGER DEFAULT 0,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    last_login_at DATETIME
, bio TEXT NOT NULL DEFAULT '', company TEXT NOT NULL DEFAULT '', location TEXT NOT NULL DEFAULT '', website TEXT NOT NULL DEFAULT '', timezone TEXT NOT NULL DEFAULT 'UTC', profile_picture_url TEXT, token_version INTEGER NOT NULL DEFAULT 1, locked_until TIMESTAMP NULL, failed_attempts INTEGER NOT NULL DEFAULT 0);
CREATE TABLE teams (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    description TEXT,
    owner_id TEXT NOT NULL,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (owner_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE team_members (
    id TEXT PRIMARY KEY,
    team_id TEXT NOT NULL,
    user_id TEXT NOT NULL,
    role TEXT NOT NULL CHECK(role IN ('owner', 'admin', 'user', 'guest')),
    invited_by TEXT,
    joined_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (team_id) REFERENCES teams(id) ON DELETE CASCADE,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    FOREIGN KEY (invited_by) REFERENCES users(id),
    UNIQUE(team_id, user_id)
);
CREATE TABLE team_invitations (
    id TEXT PRIMARY KEY,
    team_id TEXT NOT NULL,
    email TEXT NOT NULL,
    role TEXT NOT NULL CHECK(role IN ('admin', 'user', 'guest')),
    invited_by TEXT NOT NULL,
    token TEXT UNIQUE NOT NULL,
    status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending', 'accepted', 'rejected', 'expired')),
    expires_at DATETIME NOT NULL,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (team_id) REFERENCES teams(id) ON DELETE CASCADE,
    FOREIGN KEY (invited_by) REFERENCES users(id)
);
CREATE TABLE chat_sessions (
    id TEXT PRIMARY KEY,
    user_id TEXT NOT NULL,
    title TEXT,
    model TEXT NOT NULL,
    system_prompt TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP, agent_id TEXT, pinned INTEGER NOT NULL DEFAULT 0, project_id TEXT,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE chat_messages (
    id TEXT PRIMARY KEY,
    session_id TEXT NOT NULL,
    role TEXT NOT NULL CHECK(role IN ('user', 'assistant', 'system')),
    content TEXT NOT NULL,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP, parts TEXT, status TEXT NOT NULL DEFAULT 'complete' CHECK (status IN ('complete', 'stopped', 'error')), run_id TEXT, duration_ms INTEGER, agent_id TEXT,
    FOREIGN KEY (session_id) REFERENCES chat_sessions(id) ON DELETE CASCADE
);
CREATE TABLE skills (
    id TEXT PRIMARY KEY,
    name TEXT UNIQUE NOT NULL,
    version TEXT NOT NULL DEFAULT '1.0.0',
    description TEXT,
    enabled INTEGER DEFAULT 1,
    source TEXT NOT NULL CHECK(source IN ('bundled', 'managed', 'workspace', 'marketplace')),
    file_path TEXT NOT NULL,
    settings_schema TEXT, -- JSON
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE skill_settings (
    id TEXT PRIMARY KEY,
    skill_id TEXT NOT NULL,
    user_id TEXT NOT NULL,
    settings TEXT NOT NULL, -- JSON
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (skill_id) REFERENCES skills(id) ON DELETE CASCADE,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    UNIQUE(skill_id, user_id)
);
CREATE TABLE skill_secrets (
    id TEXT PRIMARY KEY,
    skill_id TEXT NOT NULL,
    user_id TEXT NOT NULL,
    key TEXT NOT NULL,
    encrypted_value TEXT NOT NULL,
    iv TEXT NOT NULL,
    auth_tag TEXT NOT NULL,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (skill_id) REFERENCES skills(id) ON DELETE CASCADE,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    UNIQUE(skill_id, user_id, key)
);
CREATE TABLE extensions (
    id TEXT PRIMARY KEY,
    name TEXT UNIQUE NOT NULL,
    version TEXT NOT NULL DEFAULT '1.0.0',
    description TEXT,
    type TEXT NOT NULL CHECK(type IN ('channel', 'integration', 'ui', 'other')),
    enabled INTEGER DEFAULT 1,
    file_path TEXT NOT NULL,
    config TEXT, -- JSON
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE workflows (
    id TEXT PRIMARY KEY,
    user_id TEXT NOT NULL,
    name TEXT NOT NULL,
    description TEXT,
    enabled INTEGER DEFAULT 1,
    nodes TEXT NOT NULL, -- JSON array of nodes
    edges TEXT NOT NULL, -- JSON array of edges
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE workflow_executions (
    id TEXT PRIMARY KEY,
    workflow_id TEXT NOT NULL,
    status TEXT NOT NULL CHECK(status IN ('running', 'completed', 'failed', 'cancelled')),
    started_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    completed_at DATETIME,
    error TEXT,
    logs TEXT, -- JSON
    FOREIGN KEY (workflow_id) REFERENCES workflows(id) ON DELETE CASCADE
);
CREATE TABLE credentials (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    type TEXT NOT NULL,
    encrypted_value TEXT NOT NULL,
    iv TEXT NOT NULL,
    auth_tag TEXT NOT NULL,
    description TEXT,
    skill_id TEXT,
    user_id TEXT,
    refresh_token TEXT,
    expires_at TEXT,
    scopes TEXT,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    last_used TEXT
);
CREATE TABLE scheduled_jobs (
    id TEXT PRIMARY KEY,
    user_id TEXT NOT NULL,
    name TEXT NOT NULL,
    description TEXT,
    cron_expression TEXT NOT NULL,
    enabled INTEGER DEFAULT 1,
    workflow_id TEXT,
    action TEXT NOT NULL, -- JSON (what to execute)
    last_run_at DATETIME,
    next_run_at DATETIME,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    FOREIGN KEY (workflow_id) REFERENCES workflows(id) ON DELETE SET NULL
);
CREATE TABLE memory_entries (
    id TEXT PRIMARY KEY,
    user_id TEXT NOT NULL,
    type TEXT NOT NULL CHECK(type IN ('conversation', 'fact', 'preference', 'task', 'other')),
    key TEXT NOT NULL,
    value TEXT NOT NULL,
    importance REAL DEFAULT 0.5, -- 0.0 to 1.0
    embeddings BLOB, -- Vector embeddings for semantic search (optional)
    metadata TEXT, -- JSON
    accessed_count INTEGER DEFAULT 0,
    last_accessed_at DATETIME,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    expires_at DATETIME, -- Optional expiration
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE gateway_sessions (
    id TEXT PRIMARY KEY,
    user_id TEXT NOT NULL,
    active_channels TEXT NOT NULL, -- JSON array ["whatsapp", "desktop"]
    context TEXT, -- JSON (conversation context)
    sync_enabled INTEGER DEFAULT 1,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    expires_at DATETIME,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE channel_messages (
    id TEXT PRIMARY KEY,
    session_id TEXT NOT NULL,
    channel_id TEXT NOT NULL,
    user_id TEXT NOT NULL,
    role TEXT NOT NULL CHECK(role IN ('user', 'assistant', 'system')),
    content TEXT NOT NULL,
    delivered INTEGER DEFAULT 0,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (session_id) REFERENCES gateway_sessions(id) ON DELETE CASCADE,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE agent_learning (
    id TEXT PRIMARY KEY,
    context TEXT NOT NULL,
    error TEXT,
    success INTEGER NOT NULL,
    lesson TEXT,
    solution TEXT,
    applied INTEGER DEFAULT 0,
    applied_at DATETIME,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE settings (
    id TEXT PRIMARY KEY,
    user_id TEXT, -- NULL for system-wide settings
    category TEXT NOT NULL,
    key TEXT NOT NULL,
    value TEXT NOT NULL, -- JSON
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    UNIQUE(user_id, category, key)
);
CREATE TABLE migrations (id TEXT PRIMARY KEY, name TEXT NOT NULL, applied_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE avatar_settings (
    id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
    user_id TEXT NOT NULL UNIQUE,  -- Changed from INTEGER to TEXT
    rpm_avatar_url TEXT,  -- Ready Player Me avatar URL
    voice_provider TEXT DEFAULT 'openai',  -- 'openai' or 'local'
    voice_id TEXT DEFAULT 'alloy',  -- Voice ID (alloy, echo, fable, onyx, nova, shimmer)
    language_preference TEXT DEFAULT 'auto',  -- 'auto', 'ar', 'en'
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP, bg_color TEXT DEFAULT '#09090b', bg_scene TEXT DEFAULT 'none', wall_text TEXT DEFAULT '', wall_logo_url TEXT DEFAULT '', wall_video_url TEXT DEFAULT '', wall_layout TEXT DEFAULT '{}', wall_spotify_url TEXT DEFAULT '',
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE inbox_messages (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL,

  source_type TEXT NOT NULL CHECK (source_type IN (
    'whatsapp', 'telegram', 'gmail', 'github', 'discord',
    'slack', 'webhook', 'manual', 'other'
  )),
  source_id TEXT,

  message TEXT NOT NULL,
  metadata JSON DEFAULT '{}',

  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN (
    'pending', 'processing', 'completed', 'failed', 'needs_approval'
  )),
  risk_level TEXT CHECK (risk_level IN ('low', 'medium', 'high')),
  auto_executed BOOLEAN DEFAULT 0,

  approval_needed BOOLEAN DEFAULT 0,
  approval_status TEXT CHECK (approval_status IS NULL OR approval_status IN (
    'pending', 'approved', 'denied'
  )),
  approved_by TEXT,
  approved_at DATETIME,

  result JSON,
  error TEXT,

  received_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  processed_at DATETIME,
  completed_at DATETIME
);
CREATE TABLE approval_rules (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL,

  source_type TEXT,
  action_pattern TEXT,
  risk_level TEXT CHECK (risk_level IS NULL OR risk_level IN ('low', 'medium', 'high')),

  auto_approve BOOLEAN DEFAULT 0,
  auto_deny BOOLEAN DEFAULT 0,
  priority INTEGER DEFAULT 5,

  name TEXT NOT NULL,
  description TEXT,
  enabled BOOLEAN DEFAULT 1,

  times_applied INTEGER DEFAULT 0,
  confidence_score REAL DEFAULT 0.0 CHECK (confidence_score >= 0.0 AND confidence_score <= 1.0),

  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,

  CHECK (NOT (auto_approve = 1 AND auto_deny = 1)),
  CHECK (priority >= 1 AND priority <= 10)
);
CREATE TABLE agents_config (
  id          TEXT PRIMARY KEY,
  name        TEXT NOT NULL,
  description TEXT DEFAULT '',
  emoji       TEXT DEFAULT '🤖',
  system_prompt TEXT DEFAULT '',
  model       TEXT DEFAULT 'claude-sonnet-4-5-20250929',
  provider    TEXT DEFAULT 'claude',
  is_primary  INTEGER DEFAULT 0,
  temperature REAL DEFAULT 0.7,
  max_tokens  INTEGER DEFAULT 4096,
  capabilities TEXT DEFAULT '{"webSearch":true,"fileOperations":true,"memory":true,"executeCommands":false}',
  created_at  TEXT DEFAULT (datetime('now')),
  updated_at  TEXT DEFAULT (datetime('now'))
, api_key TEXT DEFAULT '', cron_schedule TEXT, cron_enabled INTEGER DEFAULT 0, auto_approve_tasks INTEGER DEFAULT 0, last_heartbeat DATETIME, api_key_credential_id TEXT, version INTEGER NOT NULL DEFAULT 1, role TEXT, department TEXT);
CREATE TABLE agent_activity (
  id TEXT PRIMARY KEY,
  agent_id TEXT,
  task_id TEXT,
  session_id TEXT,
  action_type TEXT NOT NULL,
  tool_name TEXT,
  summary TEXT,
  metadata TEXT,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE storage_files (
  id TEXT PRIMARY KEY,
  zone TEXT NOT NULL CHECK(zone IN ('cache', 'cdn')),
  category TEXT NOT NULL,
  filename TEXT NOT NULL,
  filepath TEXT NOT NULL,
  original_name TEXT,
  mime_type TEXT,
  size_bytes INTEGER DEFAULT 0,
  description TEXT,
  tags TEXT,
  ttl TEXT NOT NULL DEFAULT 'persistent',
  expires_at DATETIME,
  source_url TEXT,
  created_by TEXT NOT NULL DEFAULT 'system',
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  last_accessed DATETIME,
  access_count INTEGER DEFAULT 0
);
CREATE TABLE user_avatars (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  user_id TEXT NOT NULL,
  name TEXT NOT NULL DEFAULT 'Avatar',
  source TEXT NOT NULL DEFAULT 'url',
  glb_url TEXT,
  local_glb_path TEXT,
  preview_url TEXT,
  bg_color TEXT DEFAULT '#0a0a0a',
  bg_scene TEXT DEFAULT 'none',
  is_active INTEGER DEFAULT 0,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE camera_sessions (
  id          TEXT    PRIMARY KEY,
  room_id     TEXT    NOT NULL DEFAULT '',       -- shareable room ID for calls
  user_id     TEXT    NOT NULL DEFAULT 'local',
  agent_id    TEXT    NOT NULL DEFAULT '',       -- agent used in this session
  mode        TEXT    NOT NULL DEFAULT 'vision', -- 'vision' | 'record' | 'call'
  started_at  TEXT    NOT NULL,                  -- ISO timestamp
  ended_at    TEXT,                              -- null while active
  duration_s  INTEGER,                           -- seconds (set on end)
  file_id     TEXT,                              -- storage file ID for recorded video
  frame_count INTEGER NOT NULL DEFAULT 0,        -- frames sent to AI
  notes       TEXT    NOT NULL DEFAULT '',
  created_at  TEXT    NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE notifications (
  id          TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(8)))),
  user_id     TEXT NOT NULL,
  title       TEXT NOT NULL,
  body        TEXT NOT NULL DEFAULT '',
  type        TEXT NOT NULL DEFAULT 'info',
  -- type: 'info' | 'success' | 'warning' | 'error' | 'agent' | 'system' | 'reminder'
  channel     TEXT NOT NULL DEFAULT 'in_app',
  -- channel: 'in_app' | 'email' | 'push' | 'whatsapp' | 'sound'
  is_read     INTEGER NOT NULL DEFAULT 0,
  action_url  TEXT,
  meta        TEXT,    -- JSON blob for extra structured data
  created_at  DATETIME DEFAULT CURRENT_TIMESTAMP, source TEXT DEFAULT 'system',
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE notification_settings (
  id                   TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(8)))),
  user_id              TEXT NOT NULL UNIQUE,

  -- ── Channels ──────────────────────────────────────────────
  channel_in_app       INTEGER NOT NULL DEFAULT 1,
  channel_email        INTEGER NOT NULL DEFAULT 0,
  channel_push         INTEGER NOT NULL DEFAULT 0,
  channel_whatsapp     INTEGER NOT NULL DEFAULT 0,
  channel_sound        INTEGER NOT NULL DEFAULT 1,

  -- ── Email config ──────────────────────────────────────────
  email_address        TEXT,
  email_digest         TEXT NOT NULL DEFAULT 'realtime',
  -- digest: 'realtime' | 'hourly' | 'daily' | 'weekly' | 'never'

  -- ── WhatsApp config ───────────────────────────────────────
  whatsapp_phone       TEXT,

  -- ── Do Not Disturb ────────────────────────────────────────
  dnd_enabled          INTEGER NOT NULL DEFAULT 0,
  dnd_start            TEXT NOT NULL DEFAULT '22:00',  -- HH:MM
  dnd_end              TEXT NOT NULL DEFAULT '08:00',  -- HH:MM

  -- ── Event toggles ─────────────────────────────────────────
  notify_task_complete INTEGER NOT NULL DEFAULT 1,
  notify_agent_error   INTEGER NOT NULL DEFAULT 1,
  notify_skill_exec    INTEGER NOT NULL DEFAULT 0,
  notify_workflow      INTEGER NOT NULL DEFAULT 1,
  notify_security      INTEGER NOT NULL DEFAULT 1,
  notify_system        INTEGER NOT NULL DEFAULT 1,

  -- ── Push subscription (Web Push API) ─────────────────────
  push_subscription    TEXT,  -- JSON WebPushSubscription object

  updated_at           DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE notification_schedules (
  id             TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(8)))),
  user_id        TEXT NOT NULL,
  title          TEXT NOT NULL,
  body           TEXT NOT NULL DEFAULT '',
  type           TEXT NOT NULL DEFAULT 'reminder',

  -- ── Timing ────────────────────────────────────────────────
  schedule_type  TEXT NOT NULL DEFAULT 'daily',
  -- 'once' | 'daily' | 'weekly' | 'weekdays' | 'weekends' | 'custom'
  schedule_time  TEXT NOT NULL DEFAULT '09:00',  -- HH:MM (24h)
  schedule_days  TEXT,        -- JSON [0-6] for 'weekly'/'custom'; 0=Sun
  schedule_date  TEXT,        -- YYYY-MM-DD for 'once'

  -- ── Delivery ──────────────────────────────────────────────
  channels       TEXT NOT NULL DEFAULT '["in_app"]',  -- JSON string[]

  -- ── State ─────────────────────────────────────────────────
  is_active      INTEGER NOT NULL DEFAULT 1,
  last_fired_at  DATETIME,
  next_fire_at   DATETIME,

  created_at     DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE waf_scans (
  id              TEXT    PRIMARY KEY,
  target_url      TEXT    NOT NULL,
  scan_type       TEXT    NOT NULL DEFAULT 'external', -- 'external' | 'self'
  waf_detected    INTEGER NOT NULL DEFAULT 0,          -- boolean (0/1)
  waf_type        TEXT,                                -- e.g. 'Cloudflare', 'AWS WAF'
  waf_confidence  INTEGER NOT NULL DEFAULT 0,          -- 0-100 confidence score
  total_payloads  INTEGER NOT NULL DEFAULT 0,
  blocked_count   INTEGER NOT NULL DEFAULT 0,
  passed_count    INTEGER NOT NULL DEFAULT 0,
  bypass_rate     REAL    NOT NULL DEFAULT 0,          -- 0.0 - 1.0 (passed / total)
  risk_level      TEXT,                                -- 'low' | 'medium' | 'high' | 'critical'
  results_json    TEXT,                                -- full JSON results blob
  status          TEXT    NOT NULL DEFAULT 'pending',  -- 'running' | 'complete' | 'error'
  started_at      TEXT    NOT NULL,
  ended_at        TEXT,
  created_at      TEXT    NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE extension_configs (
  extension_id  TEXT    PRIMARY KEY,
  config_json   TEXT    NOT NULL DEFAULT '{}',
  enabled       INTEGER NOT NULL DEFAULT 0,           -- boolean (0/1)
  installed_at  TEXT    NOT NULL DEFAULT (datetime('now')),
  updated_at    TEXT    NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE extension_migrations (
  extension_id  TEXT NOT NULL,
  filename      TEXT NOT NULL,
  ran_at        TEXT NOT NULL DEFAULT (datetime('now')),
  PRIMARY KEY (extension_id, filename)
);
CREATE TABLE user_worlds (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL,
  name TEXT NOT NULL,
  description TEXT,
  glb_file_id TEXT,
  thumbnail_file_id TEXT,
  is_public INTEGER DEFAULT 0,
  max_players INTEGER DEFAULT 1,
  spawn_position_x REAL DEFAULT 0,
  spawn_position_y REAL DEFAULT 0,
  spawn_position_z REAL DEFAULT 5,
  created_at TEXT DEFAULT (datetime('now')),
  updated_at TEXT DEFAULT (datetime('now'))
);
CREATE TABLE phone_numbers (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  phone_number TEXT NOT NULL UNIQUE,  -- E.164 format: +14155552671
  friendly_name TEXT,
  country_code TEXT,  -- US, SA, GB, etc.
  capabilities TEXT,  -- JSON: {"voice":true,"sms":true,"mms":false}
  provider TEXT DEFAULT 'twilio',  -- twilio, google, vonage
  provider_sid TEXT,  -- Provider's unique identifier (e.g. Twilio number SID)
  status TEXT DEFAULT 'active',  -- active, suspended, released
  monthly_cost REAL,  -- USD cost per month
  purchased_at TEXT,
  created_at TEXT DEFAULT (datetime('now')),
  updated_at TEXT DEFAULT (datetime('now'))
);
CREATE TABLE call_points (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  name TEXT NOT NULL,
  description TEXT,
  phone_number_id TEXT,  -- FK to phone_numbers.id
  agent_id TEXT,  -- FK to agents_config.id
  workflow_id TEXT,  -- FK to workflows.id (optional)

  -- Voice Settings (can override user's avatar settings)
  voice_provider TEXT DEFAULT 'openai',  -- openai, local
  voice_id TEXT DEFAULT 'alloy',  -- alloy, echo, fable, onyx, nova, shimmer
  language_preference TEXT DEFAULT 'auto',  -- auto, ar, en

  -- Call Routing Settings
  greeting_message TEXT DEFAULT 'Hello, how can I help you?',
  ivr_menu TEXT,  -- JSON: IVR menu tree structure
  max_call_duration INTEGER DEFAULT 600,  -- seconds (10 min default)
  record_calls INTEGER DEFAULT 1,  -- 0=no, 1=yes
  transcription_provider TEXT DEFAULT 'whisper',  -- whisper, twilio, both, none

  -- Business Hours & Routing
  business_hours TEXT,  -- JSON: {"mon":{"start":"09:00","end":"17:00"},"tue":{...},...}
  after_hours_message TEXT DEFAULT 'We are currently closed. Please call back during business hours.',
  transfer_number TEXT,  -- Fallback number if agent fails

  -- Status
  enabled INTEGER DEFAULT 1,  -- 0=disabled, 1=enabled
  created_at TEXT DEFAULT (datetime('now')),
  updated_at TEXT DEFAULT (datetime('now')),

  FOREIGN KEY (phone_number_id) REFERENCES phone_numbers(id) ON DELETE SET NULL,
  FOREIGN KEY (agent_id) REFERENCES agents_config(id) ON DELETE SET NULL,
  FOREIGN KEY (workflow_id) REFERENCES workflows(id) ON DELETE SET NULL
);
CREATE TABLE call_sessions (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  call_point_id TEXT,  -- FK to call_points.id
  direction TEXT NOT NULL CHECK(direction IN ('inbound', 'outbound')),

  -- Call Participants
  from_number TEXT NOT NULL,  -- E.164 format
  to_number TEXT NOT NULL,    -- E.164 format
  caller_name TEXT,            -- Caller ID name (if available)

  -- Provider Metadata
  call_sid TEXT UNIQUE,  -- Twilio/Google Call SID
  provider TEXT DEFAULT 'twilio',  -- Which provider handled this call
  status TEXT DEFAULT 'queued',  -- queued, ringing, in-progress, completed, failed, busy, no-answer, cancelled

  -- Timing
  started_at TEXT,   -- Call initiated
  answered_at TEXT,  -- Call answered
  ended_at TEXT,     -- Call ended
  duration_seconds INTEGER,  -- Total call duration

  -- Content
  recording_url TEXT,  -- Provider's cloud recording URL (temporary)
  recording_file_id TEXT,  -- FK to storage_files.id (local permanent copy)
  transcript TEXT,  -- Full conversation transcript (post-call)

  -- AI Interaction
  agent_id TEXT,  -- Which agent handled this call
  workflow_execution_id TEXT,  -- FK to workflow_executions.id (if workflow triggered)
  conversation_summary TEXT,  -- AI-generated summary

  created_at TEXT DEFAULT (datetime('now')),

  FOREIGN KEY (call_point_id) REFERENCES call_points(id) ON DELETE SET NULL,
  FOREIGN KEY (agent_id) REFERENCES agents_config(id) ON DELETE SET NULL,
  FOREIGN KEY (workflow_execution_id) REFERENCES workflow_executions(id) ON DELETE SET NULL,
  FOREIGN KEY (recording_file_id) REFERENCES storage_files(id) ON DELETE SET NULL
);
CREATE TABLE call_messages (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  call_session_id TEXT NOT NULL,
  role TEXT NOT NULL CHECK(role IN ('caller', 'agent', 'system')),  -- Who said this
  content TEXT NOT NULL,  -- Message text
  timestamp TEXT NOT NULL DEFAULT (datetime('now')),
  audio_url TEXT,  -- Individual message audio chunk (optional)

  FOREIGN KEY (call_session_id) REFERENCES call_sessions(id) ON DELETE CASCADE
);
CREATE TABLE cron_jobs (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  description TEXT,
  cron_expression TEXT NOT NULL,
  action_type TEXT NOT NULL,
  -- 'execute-skill' | 'send-message' | 'api-call' | 'run-workflow' | 'custom'
  action_data TEXT NOT NULL,
  -- JSON stringified action configuration
  enabled INTEGER NOT NULL DEFAULT 1,
  last_run DATETIME,
  next_run DATETIME,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE job_executions (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  job_id TEXT NOT NULL,
  success INTEGER NOT NULL,
  -- 1 for success, 0 for failure
  output TEXT,
  -- JSON stringified output
  error TEXT,
  -- Error message if failed
  executed_at DATETIME NOT NULL,
  duration INTEGER,
  -- Duration in milliseconds
  FOREIGN KEY (job_id) REFERENCES cron_jobs(id) ON DELETE CASCADE
);
CREATE TABLE dashboard_widgets (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  description TEXT,
  component_type TEXT NOT NULL, -- stats, chart, list, table, calendar, activity
  extension_id TEXT, -- NULL for system widgets, extension ID for extension widgets
  default_size TEXT DEFAULT 'medium', -- small, medium, large, full
  icon TEXT,
  category TEXT, -- analytics, tasks, communications, storage, team
  data_endpoint TEXT, -- API endpoint to fetch widget data
  refresh_interval INTEGER DEFAULT 60000, -- milliseconds (default: 1 minute)
  settings_schema TEXT, -- JSON: widget-specific settings schema
  created_at TEXT DEFAULT (datetime('now'))
);
CREATE TABLE user_dashboard_layouts (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL,
  layout_name TEXT DEFAULT 'default',
  widgets TEXT NOT NULL, -- JSON: [{widgetId, x, y, w, h, settings}]
  is_active INTEGER DEFAULT 1,
  created_at TEXT DEFAULT (datetime('now')),
  updated_at TEXT DEFAULT (datetime('now')),
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE calendar_sources (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL,
  name TEXT NOT NULL,
  type TEXT NOT NULL, -- google, ical, caldav, webcal, manual
  url TEXT, -- iCal URL or CalDAV URL
  color TEXT DEFAULT '#3b82f6',
  is_enabled INTEGER DEFAULT 1,
  is_primary INTEGER DEFAULT 0, -- primary calendar for new events

  -- Google Calendar OAuth
  google_calendar_id TEXT, -- e.g., user@gmail.com or calendar_id@group.calendar.google.com
  google_access_token TEXT,
  google_refresh_token TEXT,
  google_token_expiry TEXT,

  -- Sync settings
  sync_enabled INTEGER DEFAULT 1,
  sync_interval INTEGER DEFAULT 300, -- seconds (5 minutes default)
  last_synced_at TEXT,
  sync_status TEXT DEFAULT 'pending', -- pending, syncing, success, error
  sync_error TEXT,

  created_at TEXT DEFAULT (datetime('now')),
  updated_at TEXT DEFAULT (datetime('now')), description TEXT, permission TEXT DEFAULT 'read_write', allow_agent_access INTEGER DEFAULT 1,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE calendar_events (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL,
  calendar_source_id TEXT, -- NULL for manual events, references calendar_sources for synced events

  -- Event details
  title TEXT NOT NULL,
  description TEXT,
  location TEXT,

  -- Time
  start_time TEXT NOT NULL, -- ISO 8601 datetime
  end_time TEXT NOT NULL,
  is_all_day INTEGER DEFAULT 0,
  timezone TEXT DEFAULT 'UTC',

  -- Recurrence
  recurrence_rule TEXT, -- RRULE format (RFC 5545)
  recurrence_exception TEXT, -- JSON array of exception dates
  parent_event_id TEXT, -- for recurring event instances

  -- Attendees
  attendees TEXT, -- JSON array: [{email, name, status: accepted/declined/tentative/needsAction}]
  organizer TEXT, -- email

  -- Status & Type
  status TEXT DEFAULT 'confirmed', -- confirmed, tentative, cancelled
  event_type TEXT DEFAULT 'event', -- event, meeting, deadline, reminder, birthday

  -- Notifications
  reminders TEXT, -- JSON array: [{method: email/popup, minutes: 15}]

  -- External sync
  external_id TEXT, -- Google Event ID or iCal UID
  external_url TEXT, -- Link to event in external calendar
  external_etag TEXT, -- For optimistic locking

  -- Metadata
  created_at TEXT DEFAULT (datetime('now')),
  updated_at TEXT DEFAULT (datetime('now')),

  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
  FOREIGN KEY (calendar_source_id) REFERENCES calendar_sources(id) ON DELETE CASCADE
);
CREATE TABLE calendar_sync_log (
  id TEXT PRIMARY KEY,
  calendar_source_id TEXT NOT NULL,

  started_at TEXT DEFAULT (datetime('now')),
  completed_at TEXT,
  status TEXT DEFAULT 'running', -- running, success, error
  error_message TEXT,

  events_added INTEGER DEFAULT 0,
  events_updated INTEGER DEFAULT 0,
  events_deleted INTEGER DEFAULT 0,

  FOREIGN KEY (calendar_source_id) REFERENCES calendar_sources(id) ON DELETE CASCADE
);
CREATE TABLE public_chat_rooms (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  description TEXT,
  owner_user_id TEXT NOT NULL,

  -- AI Configuration (Room-Specific)
  model TEXT DEFAULT 'claude-sonnet-4.5',           -- AI model: claude-sonnet-4.5, gpt-4, gemini, ollama, etc.
  system_prompt TEXT,                               -- Room-specific system prompt (overrides agent)
  agent_id TEXT,                                    -- Optional: use existing agent as base
  workflow_id TEXT,                                 -- Optional: trigger workflow on messages
  skills TEXT,                                      -- JSON array of enabled skill IDs

  -- Avatar/UI Customization (Room-Specific - Separate from Personal)
  avatar_url TEXT,                                  -- Custom avatar GLB URL for this room
  avatar_gender TEXT DEFAULT 'female',              -- male/female
  bg_color TEXT DEFAULT '#09090b',                  -- Background hex color
  bg_scene TEXT DEFAULT 'none',                     -- Scene: office, living_room, env_city, etc.
  wall_text TEXT,                                   -- Text content for wall board
  wall_logo_url TEXT,                               -- Image/logo URL for wall
  wall_video_url TEXT,                              -- YouTube or video URL for wall
  wall_layout TEXT,                                 -- JSON: { text:{x,y,w,h}, logo:{}, video:{} }
  fx_state TEXT,                                    -- JSON: FX effects configuration

  -- Access Control
  is_public INTEGER DEFAULT 1,                      -- 1=public, 0=private/invite-only
  require_auth INTEGER DEFAULT 0,                   -- 0=anonymous allowed, 1=login required
  allowed_users TEXT,                               -- JSON array of user IDs (for private rooms)

  -- Chat Settings
  max_message_length INTEGER DEFAULT 1000,
  rate_limit_seconds INTEGER DEFAULT 5,             -- Min seconds between messages per user
  enable_voice INTEGER DEFAULT 1,                   -- Voice input/output
  enable_avatar INTEGER DEFAULT 1,                  -- Show avatar viewer
  enable_developer_mode INTEGER DEFAULT 0,          -- Allow room owner to use dev mode

  -- Widget Embedding
  embed_enabled INTEGER DEFAULT 1,
  embed_size TEXT DEFAULT 'medium',                 -- small, medium, large, full
  embed_theme TEXT DEFAULT 'auto',                  -- light, dark, auto

  -- Statistics
  message_count INTEGER DEFAULT 0,
  participant_count INTEGER DEFAULT 0,

  created_at TEXT DEFAULT (datetime('now')),
  updated_at TEXT DEFAULT (datetime('now')),

  FOREIGN KEY (owner_user_id) REFERENCES users(id) ON DELETE CASCADE,
  FOREIGN KEY (agent_id) REFERENCES agents_config(id) ON DELETE SET NULL,
  FOREIGN KEY (workflow_id) REFERENCES workflows(id) ON DELETE SET NULL
);
CREATE TABLE public_chat_messages (
  id TEXT PRIMARY KEY,
  room_id TEXT NOT NULL,
  user_id TEXT,                                     -- NULL for anonymous users
  username TEXT NOT NULL,                           -- Display name (required for anonymous)
  role TEXT NOT NULL,                               -- 'user' or 'assistant'
  content TEXT NOT NULL,
  created_at TEXT DEFAULT (datetime('now')),

  FOREIGN KEY (room_id) REFERENCES public_chat_rooms(id) ON DELETE CASCADE,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL
);
CREATE TABLE public_chat_participants (
  id TEXT PRIMARY KEY,
  room_id TEXT NOT NULL,
  user_id TEXT,                                     -- NULL for anonymous
  username TEXT NOT NULL,                           -- Display name
  joined_at TEXT DEFAULT (datetime('now')),
  last_seen_at TEXT DEFAULT (datetime('now')),

  FOREIGN KEY (room_id) REFERENCES public_chat_rooms(id) ON DELETE CASCADE,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL
);
CREATE TABLE login_attempts (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    email TEXT NOT NULL,
    ip_address TEXT,
    user_agent TEXT,
    attempted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    success INTEGER NOT NULL DEFAULT 0 -- 0 = failed, 1 = success
);
CREATE TABLE audit_logs (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,

    -- Event details
    event_type TEXT NOT NULL,
    event_category TEXT NOT NULL,
    severity TEXT NOT NULL DEFAULT 'info',

    -- User context
    user_id TEXT,
    username TEXT,

    -- Request context
    ip_address TEXT,
    user_agent TEXT,
    request_method TEXT,
    request_path TEXT,

    -- Event-specific data
    resource_type TEXT,
    resource_id TEXT,
    action TEXT,

    -- Result
    success INTEGER NOT NULL DEFAULT 1,
    error_message TEXT,

    -- Additional metadata (JSON)
    metadata TEXT,

    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL
);
CREATE TABLE world_bots (
  id TEXT PRIMARY KEY,
  world_id TEXT NOT NULL,
  agent_id TEXT NOT NULL,
  position_x REAL NOT NULL DEFAULT 0,
  position_y REAL NOT NULL DEFAULT 0,
  position_z REAL NOT NULL DEFAULT 0,
  rotation_y REAL NOT NULL DEFAULT 0,
  animation_url TEXT,
  is_active INTEGER NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now')), behavior_type TEXT NOT NULL DEFAULT 'static'
  CHECK(behavior_type IN ('static', 'random_walk', 'patrol', 'idle', 'interactive')), patrol_path TEXT, movement_speed REAL NOT NULL DEFAULT 1.0, animation_state TEXT NOT NULL DEFAULT 'idle'
  CHECK(animation_state IN ('idle', 'walk', 'run', 'sit', 'wave', 'dance')), interaction_radius REAL NOT NULL DEFAULT 3.0, current_waypoint INTEGER NOT NULL DEFAULT 0,
  FOREIGN KEY (world_id) REFERENCES user_worlds(id) ON DELETE CASCADE,
  FOREIGN KEY (agent_id) REFERENCES agents_config(id) ON DELETE CASCADE
);
CREATE TABLE agent_performance_metrics (
  id TEXT PRIMARY KEY,
  agent_id TEXT NOT NULL,
  metric_type TEXT NOT NULL, -- 'task_success_rate', 'tool_efficiency', 'response_quality', 'error_rate'
  value REAL NOT NULL,
  sample_size INTEGER DEFAULT 0,
  period_start DATETIME NOT NULL,
  period_end DATETIME NOT NULL,
  metadata TEXT, -- JSON: {tool_name, task_type, context}
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (agent_id) REFERENCES agents_config(id) ON DELETE CASCADE
);
CREATE TABLE agent_learning_insights (
  id TEXT PRIMARY KEY,
  agent_id TEXT NOT NULL,
  insight_type TEXT NOT NULL, -- 'success_pattern', 'failure_pattern', 'optimization', 'new_capability'
  title TEXT NOT NULL,
  description TEXT NOT NULL,
  confidence REAL DEFAULT 0.5, -- 0-1 confidence score
  evidence TEXT, -- JSON: [{activity_id, timestamp, outcome}]
  applied BOOLEAN DEFAULT FALSE,
  applied_at DATETIME,
  impact_score REAL, -- Measured improvement after applying (0-1)
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (agent_id) REFERENCES agents_config(id) ON DELETE CASCADE
);
CREATE TABLE agent_evolution_history (
  id TEXT PRIMARY KEY,
  agent_id TEXT NOT NULL,
  evolution_type TEXT NOT NULL, -- 'prompt_update', 'capability_added', 'capability_removed', 'config_change'
  change_description TEXT NOT NULL,
  before_value TEXT, -- JSON snapshot before change
  after_value TEXT, -- JSON snapshot after change
  trigger_reason TEXT NOT NULL, -- Why this evolution happened
  insight_ids TEXT, -- JSON array of insight IDs that triggered this
  performance_before REAL, -- Baseline metric before change
  performance_after REAL, -- Measured metric after change
  status TEXT DEFAULT 'active', -- 'active', 'rolled_back', 'superseded'
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  rolled_back_at DATETIME,
  FOREIGN KEY (agent_id) REFERENCES agents_config(id) ON DELETE CASCADE
);
CREATE TABLE agent_evolution_config (
  agent_id TEXT PRIMARY KEY,
  enabled BOOLEAN DEFAULT TRUE,
  min_confidence_threshold REAL DEFAULT 0.7, -- Minimum confidence to apply insights
  min_sample_size INTEGER DEFAULT 10, -- Minimum activity samples before learning
  evolution_frequency TEXT DEFAULT 'daily', -- 'hourly', 'daily', 'weekly', 'manual'
  allowed_evolutions TEXT DEFAULT '["prompt_update","capability_added"]', -- JSON array
  max_evolutions_per_cycle INTEGER DEFAULT 3,
  rollback_on_degradation BOOLEAN DEFAULT TRUE,
  degradation_threshold REAL DEFAULT 0.1, -- 10% performance drop triggers rollback
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (agent_id) REFERENCES agents_config(id) ON DELETE CASCADE
);
CREATE TABLE agent_capability_usage (
  id TEXT PRIMARY KEY,
  agent_id TEXT NOT NULL,
  capability_name TEXT NOT NULL, -- 'webSearch', 'fileOperations', 'memory', etc.
  usage_count INTEGER DEFAULT 0,
  success_count INTEGER DEFAULT 0,
  failure_count INTEGER DEFAULT 0,
  avg_execution_time_ms REAL DEFAULT 0,
  last_used_at DATETIME,
  first_used_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (agent_id) REFERENCES agents_config(id) ON DELETE CASCADE,
  UNIQUE(agent_id, capability_name)
);
CREATE TABLE cost_analytics (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id TEXT NOT NULL,
  session_id TEXT NOT NULL,
  timestamp INTEGER NOT NULL,
  model_used TEXT NOT NULL CHECK(model_used IN ('haiku', 'sonnet', 'opus')),
  task_complexity TEXT NOT NULL CHECK(task_complexity IN ('simple', 'medium', 'complex')),
  message_length INTEGER NOT NULL DEFAULT 0,
  tools_used TEXT NOT NULL DEFAULT '',
  estimated_savings_percent INTEGER NOT NULL DEFAULT 0,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE skill_sources (
  id TEXT PRIMARY KEY DEFAULT ('src_' || lower(hex(randomblob(16)))),
  name TEXT NOT NULL,
  type TEXT NOT NULL CHECK(type IN ('github', 'api', 'local')),
  repo_url TEXT, -- For GitHub sources: 'anthropics/skills'
  api_url TEXT, -- For API sources
  is_enabled INTEGER DEFAULT 1,
  priority INTEGER DEFAULT 0, -- Higher priority = searched first
  created_at TEXT DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE installed_skills (
  id TEXT PRIMARY KEY DEFAULT ('skill_' || lower(hex(randomblob(16)))),
  source_id TEXT NOT NULL,
  skill_name TEXT NOT NULL, -- e.g., 'pdf-extractor'
  display_name TEXT, -- Human-readable name
  description TEXT,
  category TEXT, -- 'creative', 'development', 'enterprise', 'document'
  file_path TEXT NOT NULL, -- Local path to SKILL.md
  metadata TEXT, -- JSON: author, version, tags, etc.
  is_enabled INTEGER DEFAULT 1,
  install_date TEXT DEFAULT CURRENT_TIMESTAMP,
  last_used TEXT,
  usage_count INTEGER DEFAULT 0,
  FOREIGN KEY (source_id) REFERENCES skill_sources(id) ON DELETE CASCADE,
  UNIQUE(source_id, skill_name)
);
CREATE TABLE memories (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL,
  type TEXT NOT NULL,
  content TEXT NOT NULL,
  embedding TEXT,
  memory_layer TEXT DEFAULT 'factual',
  status TEXT DEFAULT 'active',
  metadata TEXT,
  importance_score REAL DEFAULT 0.5,
  tags TEXT,
  created_at TEXT NOT NULL,
  last_accessed_at INTEGER,
  access_count INTEGER DEFAULT 0,
  expiry_timestamp INTEGER,
  consolidation_status TEXT DEFAULT 'pending'
, visibility TEXT DEFAULT 'private' CHECK(visibility IN ('private', 'team', 'public')), source_agent_id TEXT, is_team_critical INTEGER DEFAULT 0 CHECK(is_team_critical IN (0, 1)), team_id TEXT, quality_score REAL DEFAULT 50.0 CHECK(quality_score >= 0 AND quality_score <= 100), context TEXT, outcomes TEXT, emotions TEXT, related_memory_ids TEXT, completeness_score REAL DEFAULT 0.5, clarity_score REAL DEFAULT 0.5, usefulness_score REAL DEFAULT 0.5, auto_enriched INTEGER DEFAULT 0 CHECK(auto_enriched IN (0, 1)), enriched_at TEXT, needs_improvement INTEGER DEFAULT 0 CHECK(needs_improvement IN (0, 1)), drawer_kind TEXT, drawer_key TEXT, embedding_model TEXT, embedding_dims INTEGER);
CREATE TABLE memory_consolidation_log (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  run_timestamp INTEGER NOT NULL,
  memories_consolidated INTEGER DEFAULT 0,
  memories_promoted INTEGER DEFAULT 0,
  memories_expired INTEGER DEFAULT 0,
  duration_ms INTEGER,
  status TEXT DEFAULT 'success' CHECK (status IN ('success', 'failed', 'partial')),
  error_message TEXT,
  created_at TEXT DEFAULT (datetime('now'))
);
CREATE TABLE user_animations (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  user_id TEXT NOT NULL,
  name TEXT NOT NULL DEFAULT 'Custom Animation',
  filename TEXT NOT NULL,
  format TEXT NOT NULL DEFAULT 'glb',
  category TEXT NOT NULL DEFAULT 'custom',
  local_path TEXT NOT NULL,
  file_size INTEGER DEFAULT 0,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE extension_usage_stats (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  extension_id TEXT NOT NULL,
  date DATE NOT NULL,
  api_calls INTEGER DEFAULT 0,
  storage_files INTEGER DEFAULT 0,
  storage_bytes INTEGER DEFAULT 0,
  error_count INTEGER DEFAULT 0,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(extension_id, date)
);
CREATE TABLE extension_registry (
  id TEXT PRIMARY KEY, -- Extension ID (e.g., 'weather-api')
  name TEXT NOT NULL, -- Display name
  description TEXT, -- Short description
  author TEXT NOT NULL, -- Author name or organization
  author_email TEXT, -- Contact email
  author_url TEXT, -- Author website/GitHub
  version TEXT NOT NULL, -- Current version (semver)
  type TEXT NOT NULL CHECK(type IN ('app', 'channel', 'tool', 'integration')), -- Extension type
  category TEXT, -- Category (productivity, communication, developer-tools, etc.)
  tags TEXT, -- JSON array of tags for search
  icon_url TEXT, -- Icon image URL
  screenshot_urls TEXT, -- JSON array of screenshot URLs
  download_url TEXT NOT NULL, -- Direct download URL for extension package
  homepage_url TEXT, -- Extension homepage/docs
  repository_url TEXT, -- GitHub/GitLab repo URL
  license TEXT DEFAULT 'MIT', -- License type
  min_agent_version TEXT, -- Minimum Agent Player version required
  permissions TEXT, -- JSON array of required permissions
  dependencies TEXT, -- JSON array of required extension dependencies
  install_count INTEGER DEFAULT 0, -- Total installation count
  rating_avg REAL DEFAULT 0.0, -- Average rating (0-5)
  rating_count INTEGER DEFAULT 0, -- Number of ratings
  featured BOOLEAN DEFAULT 0, -- Featured extension (curated by admin)
  verified BOOLEAN DEFAULT 0, -- Verified by admin
  status TEXT DEFAULT 'active' CHECK(status IN ('active', 'deprecated', 'removed')),
  published_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE extension_versions (
  id TEXT PRIMARY KEY,
  extension_id TEXT NOT NULL, -- FK to extension_registry.id
  version TEXT NOT NULL, -- Version number (semver)
  changelog TEXT, -- Release notes
  download_url TEXT NOT NULL, -- Download URL for this version
  min_agent_version TEXT, -- Minimum Agent Player version
  breaking_changes BOOLEAN DEFAULT 0, -- Has breaking changes from previous version
  release_date DATETIME DEFAULT CURRENT_TIMESTAMP,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (extension_id) REFERENCES extension_registry(id) ON DELETE CASCADE,
  UNIQUE(extension_id, version)
);
CREATE TABLE extension_installations (
  id TEXT PRIMARY KEY,
  extension_id TEXT NOT NULL, -- FK to extension_registry.id
  user_id TEXT NOT NULL, -- FK to users.id
  installed_version TEXT NOT NULL, -- Currently installed version
  install_date DATETIME DEFAULT CURRENT_TIMESTAMP,
  last_update_check DATETIME, -- Last time checked for updates
  auto_update BOOLEAN DEFAULT 1, -- Auto-update enabled
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(extension_id, user_id)
);
CREATE TABLE extension_reviews (
  id TEXT PRIMARY KEY,
  extension_id TEXT NOT NULL, -- FK to extension_registry.id
  user_id TEXT NOT NULL, -- FK to users.id
  rating INTEGER NOT NULL CHECK(rating >= 1 AND rating <= 5), -- 1-5 stars
  review_title TEXT,
  review_text TEXT,
  helpful_count INTEGER DEFAULT 0, -- Upvote count
  version TEXT, -- Version reviewed
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (extension_id) REFERENCES extension_registry(id) ON DELETE CASCADE,
  UNIQUE(extension_id, user_id) -- One review per user per extension
);
CREATE TABLE extension_update_queue (
  id TEXT PRIMARY KEY,
  extension_id TEXT NOT NULL, -- FK to extension_registry.id
  user_id TEXT NOT NULL, -- FK to users.id
  current_version TEXT NOT NULL, -- Currently installed version
  target_version TEXT NOT NULL, -- Version to update to
  status TEXT DEFAULT 'pending' CHECK(status IN ('pending', 'in_progress', 'completed', 'failed')),
  error_message TEXT, -- Error if update failed
  scheduled_at DATETIME DEFAULT CURRENT_TIMESTAMP, -- When update was scheduled
  completed_at DATETIME, -- When update finished
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE extension_dependencies (
  id TEXT PRIMARY KEY,
  extension_id TEXT NOT NULL, -- FK to extension_registry.id (the dependent extension)
  depends_on_id TEXT NOT NULL, -- FK to extension_registry.id (the required extension)
  min_version TEXT, -- Minimum version required
  max_version TEXT, -- Maximum version allowed (optional)
  required BOOLEAN DEFAULT 1, -- If 0, dependency is optional
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (extension_id) REFERENCES extension_registry(id) ON DELETE CASCADE,
  FOREIGN KEY (depends_on_id) REFERENCES extension_registry(id) ON DELETE CASCADE,
  UNIQUE(extension_id, depends_on_id)
);
CREATE TABLE evaluation_sessions (
  id TEXT PRIMARY KEY,
  agent_id TEXT NOT NULL,
  evaluator_type TEXT NOT NULL CHECK(evaluator_type IN ('manual', 'automated', 'scheduled')),
  start_time DATETIME NOT NULL,
  end_time DATETIME,
  period_start DATETIME NOT NULL,
  period_end DATETIME NOT NULL,
  status TEXT DEFAULT 'running' CHECK(status IN ('running', 'completed', 'failed')),
  overall_score REAL, -- 0-100 composite score
  metadata TEXT, -- JSON: {config, filters, context}
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (agent_id) REFERENCES agents_config(id) ON DELETE CASCADE
);
CREATE TABLE reasoning_scores (
  id TEXT PRIMARY KEY,
  session_id TEXT NOT NULL,
  agent_id TEXT NOT NULL,
  message_id TEXT, -- Reference to chat message
  coherence_score REAL NOT NULL CHECK(coherence_score >= 0 AND coherence_score <= 100),
  logical_flow_score REAL, -- 0-100
  context_awareness_score REAL, -- 0-100
  completeness_score REAL, -- 0-100
  clarity_score REAL, -- 0-100
  analysis TEXT, -- Detailed reasoning analysis
  sample_text TEXT, -- Sample of analyzed text
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (session_id) REFERENCES evaluation_sessions(id) ON DELETE CASCADE,
  FOREIGN KEY (agent_id) REFERENCES agents_config(id) ON DELETE CASCADE
);
CREATE TABLE tool_accuracy_metrics (
  id TEXT PRIMARY KEY,
  session_id TEXT NOT NULL,
  agent_id TEXT NOT NULL,
  tool_name TEXT NOT NULL,
  total_uses INTEGER DEFAULT 0,
  correct_uses INTEGER DEFAULT 0, -- Used in appropriate context
  incorrect_uses INTEGER DEFAULT 0, -- Misused or unnecessary
  missed_opportunities INTEGER DEFAULT 0, -- Should have used but didn't
  accuracy_rate REAL, -- correct / (correct + incorrect)
  precision REAL, -- correct / total_uses
  recall REAL, -- correct / (correct + missed)
  avg_execution_time_ms REAL,
  success_rate REAL, -- executions without errors / total
  period_start DATETIME NOT NULL,
  period_end DATETIME NOT NULL,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (session_id) REFERENCES evaluation_sessions(id) ON DELETE CASCADE,
  FOREIGN KEY (agent_id) REFERENCES agents_config(id) ON DELETE CASCADE
);
CREATE TABLE safety_checks (
  id TEXT PRIMARY KEY,
  session_id TEXT NOT NULL,
  agent_id TEXT NOT NULL,
  check_type TEXT NOT NULL CHECK(check_type IN ('safety', 'bias', 'toxicity', 'privacy', 'ethics')),
  severity TEXT NOT NULL CHECK(severity IN ('info', 'low', 'medium', 'high', 'critical')),
  description TEXT NOT NULL,
  detected_pattern TEXT, -- What pattern triggered this check
  sample_text TEXT, -- Sample of problematic content
  recommendation TEXT, -- How to fix
  auto_resolved BOOLEAN DEFAULT FALSE,
  resolved_at DATETIME,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (session_id) REFERENCES evaluation_sessions(id) ON DELETE CASCADE,
  FOREIGN KEY (agent_id) REFERENCES agents_config(id) ON DELETE CASCADE
);
CREATE TABLE performance_profiles (
  id TEXT PRIMARY KEY,
  session_id TEXT NOT NULL,
  agent_id TEXT NOT NULL,
  total_requests INTEGER DEFAULT 0,
  total_tokens_input INTEGER DEFAULT 0,
  total_tokens_output INTEGER DEFAULT 0,
  avg_latency_ms REAL, -- Average response time
  p50_latency_ms REAL, -- Median
  p95_latency_ms REAL, -- 95th percentile
  p99_latency_ms REAL, -- 99th percentile
  throughput_per_minute REAL, -- Requests per minute
  total_cost_usd REAL, -- Estimated total cost
  avg_cost_per_request_usd REAL,
  cache_hit_rate REAL, -- 0-1
  error_rate REAL, -- 0-1
  timeout_rate REAL, -- 0-1
  period_start DATETIME NOT NULL,
  period_end DATETIME NOT NULL,
  metadata TEXT, -- JSON: {model_distribution, tool_usage, etc}
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (session_id) REFERENCES evaluation_sessions(id) ON DELETE CASCADE,
  FOREIGN KEY (agent_id) REFERENCES agents_config(id) ON DELETE CASCADE
);
CREATE TABLE evaluation_scores (
  id TEXT PRIMARY KEY,
  session_id TEXT NOT NULL,
  agent_id TEXT NOT NULL,
  overall_score REAL NOT NULL CHECK(overall_score >= 0 AND overall_score <= 100),
  reasoning_score REAL, -- 0-100
  tool_accuracy_score REAL, -- 0-100
  performance_score REAL, -- 0-100 (based on latency/throughput)
  cost_efficiency_score REAL, -- 0-100
  safety_score REAL, -- 0-100 (100 = no issues)
  success_rate REAL, -- 0-100
  grade TEXT CHECK(grade IN ('A+', 'A', 'B+', 'B', 'C+', 'C', 'D', 'F')),
  strengths TEXT, -- JSON array of strengths
  weaknesses TEXT, -- JSON array of weaknesses
  recommendations TEXT, -- JSON array of improvement suggestions
  period_start DATETIME NOT NULL,
  period_end DATETIME NOT NULL,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (session_id) REFERENCES evaluation_sessions(id) ON DELETE CASCADE,
  FOREIGN KEY (agent_id) REFERENCES agents_config(id) ON DELETE CASCADE,
  UNIQUE(session_id, agent_id)
);
CREATE TABLE memory_deduplication_log (
  id TEXT PRIMARY KEY,
  run_timestamp INTEGER NOT NULL,
  duplicates_found INTEGER DEFAULT 0,
  memories_merged INTEGER DEFAULT 0,
  memories_deleted INTEGER DEFAULT 0,
  duration_ms INTEGER,
  status TEXT DEFAULT 'success' CHECK (status IN ('success', 'failed', 'partial')),
  error_message TEXT,
  created_at TEXT DEFAULT (datetime('now'))
);
CREATE TABLE memory_sharing_audit (
  id TEXT PRIMARY KEY,
  memory_id TEXT NOT NULL,
  action TEXT NOT NULL CHECK(action IN ('shared', 'unshared', 'visibility_changed', 'marked_critical', 'unmarked_critical')),
  actor_agent_id TEXT,
  old_visibility TEXT,
  new_visibility TEXT,
  reason TEXT,
  created_at TEXT DEFAULT (datetime('now')),
  FOREIGN KEY (memory_id) REFERENCES memories(id) ON DELETE CASCADE
);
CREATE TABLE memory_quality_history (
  id TEXT PRIMARY KEY,
  memory_id TEXT NOT NULL,
  old_quality_score REAL,
  new_quality_score REAL,
  improvement_type TEXT CHECK(improvement_type IN ('auto_enrichment', 'manual_edit', 'consolidation', 'user_feedback')),
  changes_made TEXT, -- JSON object describing what changed
  created_at TEXT DEFAULT (datetime('now')),
  FOREIGN KEY (memory_id) REFERENCES memories(id) ON DELETE CASCADE
);
CREATE TABLE memory_relationships (
  id TEXT PRIMARY KEY,
  source_memory_id TEXT NOT NULL,
  target_memory_id TEXT NOT NULL,
  relationship_type TEXT NOT NULL CHECK(relationship_type IN ('similar', 'related', 'contradicts', 'supports', 'follows', 'prerequisite')),
  strength REAL DEFAULT 0.5 CHECK(strength >= 0 AND strength <= 1), -- Relationship strength
  auto_detected INTEGER DEFAULT 0 CHECK(auto_detected IN (0, 1)), -- Auto vs manual
  created_at TEXT DEFAULT (datetime('now')),
  FOREIGN KEY (source_memory_id) REFERENCES memories(id) ON DELETE CASCADE,
  FOREIGN KEY (target_memory_id) REFERENCES memories(id) ON DELETE CASCADE,
  UNIQUE(source_memory_id, target_memory_id, relationship_type)
);
CREATE TABLE memory_enrichment_log (
  id TEXT PRIMARY KEY,
  memory_id TEXT NOT NULL,
  enrichment_type TEXT NOT NULL CHECK(enrichment_type IN ('tags', 'emotions', 'context', 'outcomes', 'relationships', 'quality_score')),
  before_value TEXT,
  after_value TEXT,
  confidence REAL DEFAULT 0.5 CHECK(confidence >= 0 AND confidence <= 1),
  created_at TEXT DEFAULT (datetime('now')),
  FOREIGN KEY (memory_id) REFERENCES memories(id) ON DELETE CASCADE
);
CREATE TABLE onboarding_state (
  user_id TEXT PRIMARY KEY,
  current_step INTEGER NOT NULL DEFAULT 1,
  answers TEXT NOT NULL DEFAULT '{}',
  completed INTEGER NOT NULL DEFAULT 0,
  skipped INTEGER NOT NULL DEFAULT 0,
  completed_at DATETIME,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE "skill_usage_log" (
  id TEXT PRIMARY KEY DEFAULT ('log_' || lower(hex(randomblob(16)))),
  skill_id TEXT NOT NULL,
  user_id TEXT,
  agent_id TEXT,
  used_at TEXT DEFAULT CURRENT_TIMESTAMP,
  session_context TEXT, -- What was the user trying to do?
  success INTEGER, -- 1 = success, 0 = failed
  FOREIGN KEY (skill_id) REFERENCES installed_skills(id) ON DELETE CASCADE,
  FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL
);
CREATE TABLE agent_grant_profiles (
  agent_id TEXT PRIMARY KEY,
  source TEXT NOT NULL,
  parent_agent_id TEXT,
  updated_by TEXT,
  created_at TEXT DEFAULT (datetime('now')),
  updated_at TEXT DEFAULT (datetime('now')), version INTEGER NOT NULL DEFAULT 1,
  FOREIGN KEY (agent_id) REFERENCES agents_config(id) ON DELETE CASCADE
);
CREATE TABLE agent_tool_grants (
  agent_id TEXT NOT NULL,
  tool_name TEXT NOT NULL,
  scopes TEXT,
  granted_by TEXT,
  created_at TEXT DEFAULT (datetime('now')),
  PRIMARY KEY (agent_id, tool_name),
  FOREIGN KEY (agent_id) REFERENCES agents_config(id) ON DELETE CASCADE
);
CREATE TABLE tool_approvals (
  id TEXT PRIMARY KEY,
  status TEXT NOT NULL CHECK (status IN ('pending', 'approved', 'denied', 'executed', 'failed', 'expired')),
  agent_id TEXT,
  user_id TEXT,
  session_id TEXT,
  tool_name TEXT NOT NULL,
  category TEXT,
  params_encrypted TEXT NOT NULL,
  params_iv TEXT NOT NULL,
  params_tag TEXT NOT NULL,
  params_preview TEXT,
  origin TEXT,
  delegated_from TEXT,
  requested_at TEXT NOT NULL DEFAULT (datetime('now')),
  decided_at TEXT,
  decided_by TEXT,
  executed_at TEXT,
  result_preview TEXT,
  error TEXT
, params_hash TEXT, params_salt TEXT, preview_truncated INTEGER DEFAULT 0, run_scope TEXT, run_id TEXT, run_step INTEGER);
CREATE TABLE agent_personality_versions (
  agent_id TEXT NOT NULL,
  version INTEGER NOT NULL CHECK (version >= 1),
  traits TEXT NOT NULL,
  preset TEXT,
  dialect TEXT NOT NULL,
  locked INTEGER NOT NULL DEFAULT 0 CHECK (locked IN (0, 1)),
  locked_traits TEXT NOT NULL DEFAULT '[]',
  source TEXT NOT NULL,
  based_on_version INTEGER,
  note TEXT,
  created_by TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  PRIMARY KEY (agent_id, version),
  FOREIGN KEY (agent_id) REFERENCES agents_config(id) ON DELETE CASCADE
);
CREATE TABLE used_agent_names (
  name_key TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  language TEXT,
  agent_id TEXT NOT NULL,
  reason TEXT NOT NULL,
  reserved_by TEXT,
  reserved_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE memory_weekly_summaries (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL,
  period_start TEXT NOT NULL,
  period_end TEXT NOT NULL,
  digest TEXT NOT NULL,
  text TEXT NOT NULL,
  model_text TEXT,
  model TEXT,
  created_by TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
CREATE TABLE "memory_versions" (
  id TEXT PRIMARY KEY,
  memory_id TEXT NOT NULL,
  user_id TEXT NOT NULL,
  drawer_kind TEXT NOT NULL,
  drawer_key TEXT NOT NULL DEFAULT '',
  drawer_revision INTEGER NOT NULL,
  version INTEGER NOT NULL,
  change TEXT NOT NULL CHECK(change IN ('baseline', 'create', 'update', 'delete', 'forget')),
  type TEXT,
  content TEXT,
  importance_score REAL,
  proposal_id TEXT,
  created_by TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  reason TEXT,
  UNIQUE(memory_id, version)
);
CREATE TABLE memory_retention_config (
  user_id TEXT PRIMARY KEY,
  enabled INTEGER NOT NULL DEFAULT 0 CHECK(enabled IN (0, 1)),
  task_ttl_days INTEGER NOT NULL DEFAULT 90,
  experience_after_days INTEGER NOT NULL DEFAULT 180,
  experience_min_group INTEGER NOT NULL DEFAULT 3,
  updated_by TEXT,
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
CREATE TABLE memory_retention_runs (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL,
  dry_run INTEGER NOT NULL DEFAULT 0,
  actor TEXT NOT NULL,
  result TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
CREATE TABLE task_runs (
  id TEXT PRIMARY KEY,
  task_id TEXT NOT NULL,
  agent_id TEXT NOT NULL,
  user_id TEXT,
  status TEXT NOT NULL DEFAULT 'queued'
    CHECK (status IN ('queued', 'running', 'waiting_approval', 'completed', 'failed', 'cancelled')),
  status_reason TEXT,
  lease_owner TEXT,
  lease_expires_at INTEGER,
  lease_generation INTEGER NOT NULL DEFAULT 0,
  attempt INTEGER NOT NULL DEFAULT 0,
  checkpoint_step INTEGER NOT NULL DEFAULT -1,
  steps_used INTEGER NOT NULL DEFAULT 0,
  max_steps INTEGER NOT NULL,
  max_duration_ms INTEGER NOT NULL,
  active_ms INTEGER NOT NULL DEFAULT 0,
  segment_started_ms INTEGER,
  cancel_requested INTEGER NOT NULL DEFAULT 0,
  input_encrypted TEXT,
  input_iv TEXT,
  input_tag TEXT,
  output_preview TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  started_at TEXT,
  updated_at TEXT NOT NULL DEFAULT (datetime('now')),
  finished_at TEXT
, contract_encrypted TEXT, contract_iv TEXT, contract_tag TEXT, verification_status TEXT
  CHECK (verification_status IS NULL OR verification_status IN ('verified', 'failed_verification', 'needs_review')), verification_reasons TEXT, verification_round INTEGER NOT NULL DEFAULT 0, max_verification_retries INTEGER NOT NULL DEFAULT 0, review_mode TEXT, review_decision TEXT CHECK (review_decision IS NULL OR review_decision IN ('accepted', 'rejected')), reviewed_by TEXT, reviewer_kind TEXT, review_note TEXT, reviewed_at TEXT, max_cost_cents REAL, cost_cents REAL NOT NULL DEFAULT 0);
CREATE TABLE task_run_steps (
  run_id TEXT NOT NULL REFERENCES task_runs(id) ON DELETE CASCADE,
  step_index INTEGER NOT NULL,
  kind TEXT NOT NULL CHECK (kind IN ('model', 'tool')),
  tool_name TEXT,
  idempotency_key TEXT NOT NULL,
  idempotent INTEGER NOT NULL DEFAULT 0,
  status TEXT NOT NULL
    CHECK (status IN ('started', 'completed', 'failed', 'unknown', 'waiting_approval', 'retry')),
  attempt INTEGER NOT NULL DEFAULT 1,
  approval_id TEXT,
  result_encrypted TEXT,
  result_iv TEXT,
  result_tag TEXT,
  error TEXT,
  resolved_by TEXT,
  started_at TEXT NOT NULL DEFAULT (datetime('now')),
  completed_at TEXT, provider TEXT, model TEXT, input_tokens INTEGER, output_tokens INTEGER, cost_cents REAL, usage_source TEXT,
  PRIMARY KEY (run_id, step_index)
);
CREATE TABLE small_agent_runs (
  run_id TEXT PRIMARY KEY REFERENCES task_runs(id) ON DELETE CASCADE,
  task_id TEXT NOT NULL,
  requested_by TEXT NOT NULL,
  kind TEXT NOT NULL DEFAULT 'other'
    CHECK (kind IN ('lookup', 'summary', 'classification', 'draft', 'other')),
  requested_tools TEXT NOT NULL DEFAULT '[]',
  granted_tools TEXT NOT NULL DEFAULT '[]',
  drawers TEXT NOT NULL DEFAULT '[]',
  model TEXT NOT NULL,
  warnings TEXT NOT NULL DEFAULT '[]',
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
, read_root TEXT);
CREATE TABLE task_contracts (
  task_id TEXT PRIMARY KEY,
  contract_encrypted TEXT NOT NULL,
  contract_iv TEXT NOT NULL,
  contract_tag TEXT NOT NULL,
  created_by TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE task_run_verifications (
  run_id TEXT NOT NULL REFERENCES task_runs(id) ON DELETE CASCADE,
  round INTEGER NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('verified', 'failed_verification', 'needs_review')),
  reasons TEXT NOT NULL,
  checks TEXT NOT NULL,
  verifier TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  PRIMARY KEY (run_id, round)
);
CREATE TABLE paid_usage (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  day TEXT NOT NULL,
  provider TEXT NOT NULL,
  model TEXT,
  run_id TEXT,
  step_index INTEGER,
  purpose TEXT NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('reserved', 'recorded', 'released')),
  estimated_cents REAL NOT NULL,
  cost_cents REAL NOT NULL DEFAULT 0,
  input_tokens INTEGER,
  output_tokens INTEGER,
  usage_source TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE mcp_servers (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL UNIQUE,
  description TEXT,
  transport TEXT NOT NULL CHECK (transport IN ('stdio', 'http', 'sse')),
  command TEXT,
  args TEXT,
  url TEXT,
  allow_remote INTEGER NOT NULL DEFAULT 0,
  env_names TEXT,
  header_names TEXT,
  secret_credential_id TEXT,
  enabled INTEGER NOT NULL DEFAULT 0,
  launch_hash TEXT,
  approved_launch_hash TEXT,
  approved_by TEXT,
  approved_at TEXT,
  timeout_ms INTEGER NOT NULL DEFAULT 30000,
  max_result_bytes INTEGER NOT NULL DEFAULT 65536,
  status TEXT NOT NULL DEFAULT 'new',
  last_error TEXT,
  last_discovered_at TEXT,
  created_by TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
, generation TEXT);
CREATE TABLE mcp_server_tools (
  server_id TEXT NOT NULL REFERENCES mcp_servers(id) ON DELETE CASCADE,
  tool_name TEXT NOT NULL,
  registry_name TEXT NOT NULL UNIQUE,
  title TEXT,
  description TEXT,
  input_schema TEXT NOT NULL,
  annotations TEXT,
  requires_approval INTEGER,
  discovered_at TEXT NOT NULL DEFAULT (datetime('now')), fingerprint TEXT,
  PRIMARY KEY (server_id, tool_name)
);
CREATE TABLE mcp_grant_bindings (
  agent_id TEXT NOT NULL,
  tool_name TEXT NOT NULL,
  server_id TEXT NOT NULL,
  fingerprint TEXT NOT NULL,
  granted_by TEXT,
  granted_at TEXT NOT NULL DEFAULT (datetime('now')),
  PRIMARY KEY (agent_id, tool_name)
);
CREATE TABLE "memory_file_proposals" (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL,
  agent_id TEXT NOT NULL,
  drawer_kind TEXT NOT NULL,
  drawer_key TEXT NOT NULL DEFAULT '',
  base_hash TEXT NOT NULL,
  base_revision INTEGER NOT NULL,
  changes TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending', 'approved', 'rejected', 'stale', 'cancelled')),
  source TEXT NOT NULL CHECK(source IN ('upload', 'file', 'learning', 'agent', 'import')),
  note TEXT,
  created_by TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  decided_by TEXT,
  decided_at TEXT,
  applied_revision INTEGER,
  reasons TEXT,
  import_batch_id TEXT
);
CREATE TABLE memory_import_batches (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL,
  source_kind TEXT NOT NULL CHECK(source_kind IN ('claude-code', 'codex', 'chatgpt', 'text')),
  status TEXT NOT NULL DEFAULT 'preview' CHECK(status IN ('preview', 'committed', 'cancelled', 'rolled_back', 'expired')),
  latest_version INTEGER NOT NULL DEFAULT 1,
  options TEXT NOT NULL DEFAULT '{}',
  committed_version INTEGER,
  committed_hash TEXT,
  operation_key TEXT,
  receipt TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  expires_at TEXT NOT NULL,
  committed_at TEXT,
  closed_at TEXT
);
CREATE TABLE memory_import_previews (
  batch_id TEXT NOT NULL,
  version INTEGER NOT NULL,
  parent_version INTEGER,
  content_hash TEXT NOT NULL,
  files TEXT NOT NULL,
  items TEXT NOT NULL,
  summary TEXT NOT NULL,
  created_by TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  PRIMARY KEY (batch_id, version)
);
CREATE TABLE memory_import_settings (
  user_id TEXT PRIMARY KEY,
  redact_emails INTEGER NOT NULL DEFAULT 0,
  redact_phones INTEGER NOT NULL DEFAULT 0,
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
CREATE TABLE interactive_usage (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  day TEXT NOT NULL,
  provider TEXT NOT NULL,
  model TEXT,
  purpose TEXT NOT NULL,
  cost_cents REAL NOT NULL DEFAULT 0,
  input_tokens INTEGER,
  output_tokens INTEGER,
  usage_source TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE login_devices (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    email TEXT NOT NULL,
    token_hash TEXT NOT NULL UNIQUE,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    last_used_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    expires_at TEXT NOT NULL,
    failed_count INTEGER NOT NULL DEFAULT 0,
    last_failed_at TEXT
);
CREATE TABLE personality_proposals (
  id TEXT PRIMARY KEY,
  agent_id TEXT NOT NULL,
  base_version INTEGER NOT NULL CHECK (base_version >= 0),
  base_traits TEXT NOT NULL,
  proposed_traits TEXT NOT NULL,
  reason TEXT NOT NULL CHECK (length(reason) BETWEEN 1 AND 1000),
  evidence TEXT NOT NULL DEFAULT '[]',
  source TEXT NOT NULL CHECK (source IN ('agent', 'evolution', 'owner')),
  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'approved', 'rejected', 'stale', 'cancelled')),
  review_hash TEXT NOT NULL,
  created_by TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  decided_by TEXT,
  decided_at TEXT,
  decision_note TEXT CHECK (decision_note IS NULL OR length(decision_note) <= 500),
  applied_version INTEGER,
  FOREIGN KEY (agent_id) REFERENCES agents_config(id) ON DELETE CASCADE
);
CREATE TABLE evolution_proposals (
  id TEXT PRIMARY KEY,
  agent_id TEXT NOT NULL,
  kind TEXT NOT NULL CHECK (kind IN ('prompt_append', 'personality_text')),
  title TEXT NOT NULL CHECK (length(title) BETWEEN 1 AND 200),
  proposed_text TEXT NOT NULL CHECK (length(proposed_text) BETWEEN 1 AND 4000),
  reason TEXT NOT NULL CHECK (length(reason) BETWEEN 1 AND 1000),
  insight_type TEXT,
  confidence REAL,
  base_hash TEXT NOT NULL,
  source TEXT NOT NULL DEFAULT 'evolution' CHECK (source IN ('evolution')),
  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'approved', 'rejected', 'stale', 'cancelled')),
  review_hash TEXT NOT NULL,
  created_by TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  decided_by TEXT,
  decided_at TEXT,
  decision_note TEXT CHECK (decision_note IS NULL OR length(decision_note) <= 500),
  applied_history_id TEXT,
  FOREIGN KEY (agent_id) REFERENCES agents_config(id) ON DELETE CASCADE
);
CREATE TABLE "voice_messages" (
    id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
    session_id TEXT NOT NULL,
    message_id TEXT NOT NULL,
    audio_url TEXT,  -- Path to stored audio file
    language TEXT,  -- Detected language
    transcript TEXT,  -- Transcribed text
    duration_seconds REAL,  -- Audio duration
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE team_hire_batches (
  id TEXT PRIMARY KEY,
  owner_id TEXT NOT NULL,
  fingerprint TEXT NOT NULL,
  language TEXT NOT NULL,
  total INTEGER NOT NULL CHECK (total >= 1),
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE team_hire_batch_items (
  batch_id TEXT NOT NULL REFERENCES team_hire_batches(id) ON DELETE CASCADE,
  seq INTEGER NOT NULL CHECK (seq >= 1),
  department TEXT NOT NULL,
  role TEXT NOT NULL CHECK (role IN ('manager', 'specialist', 'evaluator')),
  title TEXT NOT NULL,
  preset TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'created', 'failed')),
  agent_id TEXT,
  name TEXT,
  error_code TEXT,
  updated_at TEXT NOT NULL DEFAULT (datetime('now')),
  PRIMARY KEY (batch_id, seq)
);
CREATE TABLE agent_permissions (
  agent_id TEXT PRIMARY KEY REFERENCES agents_config(id) ON DELETE CASCADE,
  memory_read TEXT NOT NULL,
  memory_write TEXT NOT NULL,
  shared_memory INTEGER NOT NULL DEFAULT 0 CHECK (shared_memory IN (0, 1)),
  modes TEXT NOT NULL,
  version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
  updated_by TEXT,
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE boards (
  id TEXT PRIMARY KEY,
  owner_id TEXT NOT NULL,
  name TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
, description TEXT NOT NULL DEFAULT '', template TEXT NOT NULL DEFAULT 'custom', color TEXT NOT NULL DEFAULT 'blue', archived INTEGER NOT NULL DEFAULT 0 CHECK (archived IN (0, 1)), version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1));
CREATE TABLE board_columns (
  id TEXT PRIMARY KEY,
  board_id TEXT NOT NULL REFERENCES boards(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  position INTEGER NOT NULL,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE board_cards (
  id TEXT PRIMARY KEY,
  board_id TEXT NOT NULL REFERENCES boards(id) ON DELETE CASCADE,
  column_id TEXT NOT NULL REFERENCES board_columns(id) ON DELETE CASCADE,
  title TEXT NOT NULL,
  description TEXT NOT NULL DEFAULT '',
  priority TEXT NOT NULL DEFAULT 'normal' CHECK (priority IN ('low', 'normal', 'high', 'urgent')),
  position INTEGER NOT NULL,
  due_date TEXT,
  task_id TEXT,
  archived INTEGER NOT NULL DEFAULT 0 CHECK (archived IN (0, 1)),
  created_by TEXT NOT NULL,
  version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1),
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
, card_type TEXT NOT NULL DEFAULT 'task' CHECK (card_type IN ('task', 'idea', 'bug', 'milestone', 'request')), start_date TEXT, cover TEXT, conversation_id TEXT);
CREATE TABLE board_card_agents (
  card_id TEXT NOT NULL REFERENCES board_cards(id) ON DELETE CASCADE,
  agent_id TEXT NOT NULL REFERENCES agents_config(id) ON DELETE CASCADE,
  PRIMARY KEY (card_id, agent_id)
);
CREATE TABLE board_card_departments (
  card_id TEXT NOT NULL REFERENCES board_cards(id) ON DELETE CASCADE,
  department TEXT NOT NULL,
  PRIMARY KEY (card_id, department)
);
CREATE TABLE board_card_comments (
  id TEXT PRIMARY KEY,
  card_id TEXT NOT NULL REFERENCES board_cards(id) ON DELETE CASCADE,
  author_kind TEXT NOT NULL CHECK (author_kind IN ('user', 'agent')),
  author_id TEXT NOT NULL,
  body TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE board_departments (
  board_id TEXT NOT NULL REFERENCES boards(id) ON DELETE CASCADE,
  department TEXT NOT NULL,
  PRIMARY KEY (board_id, department)
);
CREATE TABLE board_labels (
  id TEXT PRIMARY KEY,
  board_id TEXT NOT NULL REFERENCES boards(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  color TEXT NOT NULL,
  position INTEGER NOT NULL
);
CREATE TABLE board_card_labels (
  card_id TEXT NOT NULL REFERENCES board_cards(id) ON DELETE CASCADE,
  label_id TEXT NOT NULL REFERENCES board_labels(id) ON DELETE CASCADE,
  PRIMARY KEY (card_id, label_id)
);
CREATE TABLE board_card_checklist (
  id TEXT PRIMARY KEY,
  card_id TEXT NOT NULL REFERENCES board_cards(id) ON DELETE CASCADE,
  text TEXT NOT NULL,
  done INTEGER NOT NULL DEFAULT 0 CHECK (done IN (0, 1)),
  position INTEGER NOT NULL
);
CREATE TABLE chat_projects (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  slug TEXT NOT NULL,
  folder TEXT,
  repo_url TEXT,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  UNIQUE (user_id, slug)
);
CREATE TABLE user_prefs (
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  key TEXT NOT NULL,
  value TEXT NOT NULL,
  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (user_id, key)
);
CREATE TABLE local_agent_imports (
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  session_id TEXT NOT NULL,
  source TEXT NOT NULL,
  batch_id TEXT,
  proposed INTEGER NOT NULL DEFAULT 0,
  archive_name TEXT,
  imported_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (user_id, session_id)
);
CREATE TABLE board_card_activity (
  id TEXT PRIMARY KEY,
  card_id TEXT NOT NULL REFERENCES board_cards(id) ON DELETE CASCADE,
  kind TEXT NOT NULL CHECK (kind IN ('created', 'moved', 'done', 'comment', 'archived', 'restored')),
  actor_kind TEXT NOT NULL CHECK (actor_kind IN ('user', 'agent')),
  actor_id TEXT NOT NULL,
  detail TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE chat_memory_links (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL,
  conversation_id TEXT NOT NULL REFERENCES chat_sessions(id) ON DELETE CASCADE,
  message_id TEXT,
  kind TEXT NOT NULL CHECK (kind IN ('remembered', 'proposed')),
  memory_id TEXT,
  proposal_id TEXT,
  drawer_kind TEXT NOT NULL,
  drawer_key TEXT NOT NULL DEFAULT '',
  preview TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
